import type { MedusaRequest, MedusaResponse } from "@medusajs/framework/http"
import { ContainerRegistrationKeys } from "@medusajs/framework/utils"
import { updateOffersWorkflow } from "@mercurjs/core/workflows"
const actorId=(req:MedusaRequest)=>(req as any).auth_context?.actor_id||(req as any).auth_context?.auth_identity_id
async function sellerId(req:MedusaRequest,actor:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;const {data}=await q.graph({entity:"seller_member",fields:["seller.id"],filters:{member_id:actor},pagination:{take:1}});return data?.[0]?.seller?.id||null}
export async function DELETE(req:MedusaRequest,res:MedusaResponse){const actor=actorId(req);if(!actor)return res.status(401).json({message:"Unauthorized"});const seller=await sellerId(req,actor);const spike=req.scope.resolve("spike") as any;const rows=await spike.listSpikeDiscounts({id:req.params.id},{take:1});const d=rows[0];if(!d)return res.status(404).json({message:"Discount not found"});if(String(d.seller_id)!==String(seller))return res.status(403).json({message:"Forbidden"});await updateOffersWorkflow(req.scope).run({input:{offers:[{id:d.offer_id,prices:[{amount:Number(d.original_price),currency_code:String(d.currency_code).toLowerCase()}],metadata:{compare_at_price:null,spike_discount_id:null,spike_discount_percentage:null}}]}} as any);await spike.updateSpikeDiscounts({id:d.id,active:false});res.json({ok:true})}
